insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_80_v1'
from (values
('127.617.d.1.A',3,'A food pantry, a faith-based shelter, and a county aid office are all examples of what a student researches in this course?','["family and community services", "stock market indexes", "airline routes", "software licenses"]'::jsonb,0,'These groups meet needs of families and neighbors.','original'),
('127.617.d.1.A',4,'A student compares a nonprofit agency, a government program, and a church outreach ministry. What is the student studying?','["types of farm equipment", "types of organizations that serve families", "types of retail pricing", "types of sports leagues"]'::jsonb,1,'Agencies, organizations and faith groups all provide services.','original'),
('127.617.d.1.B',3,'Looking at jobs such as caseworker, child-care director, and youth minister is part of investigating:','["careers in deep-sea mining", "careers in video game art", "careers that focus on families and communities", "careers in aircraft repair"]'::jsonb,2,'These jobs serve people in households and neighborhoods.','original'),
('127.617.d.1.B',4,'Which question best helps a student investigate a family-services career?','["What brand of phone does the boss use?", "How many parking spaces are there?", "What color is the office building?", "What education and training does the job require?"]'::jsonb,3,'Career research looks at training, duties and outlook.','original'),
('127.617.d.1.C',3,'Counting how many residents are children, adults and seniors in a town is gathering:','["demographic data", "sports statistics", "recipe data", "weather data"]'::jsonb,0,'Demographics describe the makeup of a population.','original'),
('127.617.d.1.C',4,'A town''s population is aging quickly. What community need is most likely to grow?','["teen driving lessons only", "senior care and transportation services", "skate park rentals", "toy store inventory"]'::jsonb,1,'Older residents often need care, health and transport help.','original'),
('127.617.d.1.D',3,'Planning for the services families will need ten years from now involves studying:','["old photographs", "yesterday''s weather", "future trends", "last year''s lunch menu"]'::jsonb,2,'Trend analysis looks ahead.','original'),
('127.617.d.1.D',4,'If more parents work from home in coming years, which service might see increased demand?','["rotary phone repair", "paper map printing", "film camera developing", "flexible child-care options"]'::jsonb,3,'Changing work patterns change child-care needs.','original'),
('127.617.d.1.E',3,'Learning customs, values and behavior from family, school and peers is called:','["socialization", "erosion", "inflation", "refinancing"]'::jsonb,0,'Socialization shapes how people develop.','original'),
('127.617.d.1.E',4,'A child who learns to share by watching older siblings is an example of the role of what in human development?','["depreciation", "socialization", "photosynthesis", "fermentation"]'::jsonb,1,'People learn behavior from those around them.','original'),
('127.617.d.2.A',3,'A parent who juggles caring for a child, working a job and volunteering at church is balancing multiple:','["engine parts", "tax brackets", "roles", "passwords"]'::jsonb,2,'Family, community and career roles must be managed together.','original'),
('127.617.d.2.A',4,'Which management practice best helps a person handle several roles at once?','["ignoring all deadlines", "waiting until the last minute", "saying yes to every request", "making a weekly schedule with priorities"]'::jsonb,3,'Planning and prioritizing reduce overload.','original'),
('127.617.d.2.B',3,'Honesty, a positive attitude and the ability to listen are examples of personal:','["leadership characteristics", "insurance policies", "storage devices", "filing cabinets"]'::jsonb,0,'These traits show up in good leaders.','original'),
('127.617.d.2.B',4,'A student takes a survey and finds she is strong at motivating others but weak at staying organized. She has identified her leadership:','["phone plans", "strengths and weaknesses", "tax refunds", "travel routes"]'::jsonb,1,'Self-assessment finds what to build on.','original'),
('127.617.d.2.C',3,'Setting a goal to practice public speaking each week is part of a plan to enhance personal:','["inventory", "mileage", "leadership", "insurance"]'::jsonb,2,'A plan turns a weakness into growth.','original'),
('127.617.d.2.C',4,'A good plan for improving a leadership trait includes a clear goal, specific steps and:','["a vague wish", "no deadline", "a secret ending", "a way to measure progress"]'::jsonb,3,'Plans need checkpoints.','original'),
('127.617.d.2.D',3,'Two club members disagree about a fundraiser. Finding a solution both can accept is called:','["conflict resolution", "public speaking", "conflict creation", "budget cutting"]'::jsonb,0,'Resolution ends a disagreement fairly.','original'),
('127.617.d.2.D',4,'Which action shows a positive interpersonal skill during a disagreement?','["walking out in silence", "listening to the other view before responding", "spreading rumors", "interrupting to win"]'::jsonb,1,'Respectful listening keeps talks productive.','original'),
('127.617.d.2.E',3,'Working with others to reach a goal depends on effective strategies for:','["hidden agendas", "random guessing", "collaborative relationships", "solo competition"]'::jsonb,2,'Collaboration needs communication and trust.','original'),
('127.617.d.2.E',4,'A team that shares credit, divides tasks fairly and checks in regularly is practicing:','["procrastination", "isolation", "favoritism", "collaboration"]'::jsonb,3,'These habits build strong teams.','original'),
('127.617.d.2.F',3,'A student explains a local volunteer program to the class using slides. This is a:','["service presentation", "lab report", "tax return", "bus schedule"]'::jsonb,0,'Presentations share information about services.','original'),
('127.617.d.2.F',4,'Before delivering a presentation about community services, a student should first:','["memorize unrelated facts", "know the audience and purpose", "hide the topic", "skip rehearsal"]'::jsonb,1,'Audience and purpose guide content.','original'),
('127.617.d.2.G',3,'Running for an office in a student organization like FCCLA or HOSA is a way to practice:','["engine repair", "map reading", "leadership skills", "tax filing"]'::jsonb,2,'Student organizations build leaders.','original'),
('127.617.d.2.G',4,'Which activity best develops leadership through a career and technical student organization?','["avoiding all teamwork", "watching from the back row", "skipping meetings", "chairing a service committee"]'::jsonb,3,'Taking responsibility builds leadership.','original'),
('127.617.d.3.A',3,'Collecting coats for a shelter, cleaning a park and tutoring younger students are examples of:','["service projects", "stock trades", "tax audits", "lab experiments"]'::jsonb,0,'Service projects help the community.','original'),
('127.617.d.3.A',4,'A good service project should do what?','["cost as much as possible", "meet a real community need", "only entertain the organizers", "avoid helping anyone"]'::jsonb,1,'Projects work best when tied to a need.','original'),
('127.617.d.3.B',3,'A student who loves cooking organizes a soup supper for a shelter. She is matching her service work to her:','["shoe size", "birthday", "interests and skills", "locker number"]'::jsonb,2,'Using strengths makes service meaningful.','original'),
('127.617.d.3.B',4,'Why connect your abilities to a service-learning activity?','["so you can avoid learning", "so no one else helps", "so the project takes longer", "you contribute more and stay motivated"]'::jsonb,3,'Strengths improve results and engagement.','original'),
('127.617.d.3.C',3,'Which list shows the correct order of phases for a service-learning activity?','["plan, develop, implement, evaluate", "evaluate, implement, plan, develop", "develop, evaluate, plan, implement", "implement, plan, evaluate, develop"]'::jsonb,0,'You plan first and evaluate at the end.','original'),
('127.617.d.3.C',4,'After a canned-food drive ends, the group counts donations and discusses what went well. This is the _____ step.','["advertising", "evaluation", "fundraising", "planning"]'::jsonb,1,'Evaluation reviews results to improve.','original'),
('127.617.d.3.D',3,'Wearing gloves while picking up litter and working with a partner near traffic are examples of:','["filing rules", "travel tips", "safety practices", "decorating tips"]'::jsonb,2,'Safety protects volunteers.','original'),
('127.617.d.3.D',4,'Before a community cleanup, which safety step is most important?','["working alone at night", "skipping the instructions", "ignoring first-aid supplies", "reviewing hazards and wearing proper gear"]'::jsonb,3,'Know the risks and prepare.','original'),
('127.617.d.3.E',3,'Keeping a journal of what you learned while volunteering helps document your:','["personal growth", "phone model", "home address", "favorite snack"]'::jsonb,0,'Documentation shows learning over time.','original'),
('127.617.d.3.E',4,'A volunteer log with hours, tasks and reflections is useful later for:','["grocery lists", "portfolios and applications", "weather reports", "parking permits"]'::jsonb,1,'Records support scholarships and jobs.','original'),
('127.617.d.3.F',3,'Dressing neatly and being polite at a nursing-home visit shows appropriate:','["debt", "tardiness", "appearance and etiquette", "clutter"]'::jsonb,2,'First impressions matter in service.','original'),
('127.617.d.3.F',4,'Which choice shows proper etiquette while serving at a community event?','["ignoring guests", "texting during the shift", "arguing about assignments", "greeting people politely and staying on task"]'::jsonb,3,'Courtesy shows respect.','original'),
('127.617.d.3.G',3,'Keeping private information about the people you serve is an example of:','["ethical practice", "wasted effort", "bad manners", "loose habits"]'::jsonb,0,'Confidentiality is part of ethics.','original'),
('127.617.d.3.G',4,'A volunteer sees a neighbor at the food pantry. The ethical response is to:','["tell the whole school", "keep the visit private", "joke about it", "post it online"]'::jsonb,1,'Respecting privacy protects dignity.','original'),
('127.617.d.3.H',3,'Posters, social media posts and radio spots that promote a volunteer day are part of a:','["chemistry lab", "tax return", "public relations campaign", "fire drill"]'::jsonb,2,'PR spreads the word.','original'),
('127.617.d.3.H',4,'A strong campaign for a service event should include a clear message and:','["a hidden date", "no contact info", "confusing slogans", "a defined target audience"]'::jsonb,3,'Know who you want to reach.','original'),
('127.618.d.1.A',3,'When choosing products for clients, a stylist should look for ones that are:','["safe and effective", "expired", "untested", "unlabeled"]'::jsonb,0,'Appraising products protects clients.','original'),
('127.618.d.1.A',4,'Which is a sign that a personal care product may not be safe to use?','["it has a listed ingredients panel", "it is past its expiration date", "it has a clear label", "it is stored properly"]'::jsonb,1,'Expired products can irritate or infect.','original'),
('127.618.d.1.B',3,'A student who guides classmates calmly during a lab shows what skill?','["avoidance", "delay", "leadership", "blame"]'::jsonb,2,'Leaders keep a positive environment.','original'),
('127.618.d.1.B',4,'To maintain positive working relationships in a salon classroom, a student should:','["ignore the instructor", "gossip about peers", "refuse to help", "communicate respectfully and share tasks"]'::jsonb,3,'Respect and teamwork build relationships.','original'),
