('127.618.d.2.B',3,'A wet floor, a frayed cord and an uncovered chemical container are:','["hazards", "bonuses", "decorations", "appointments"]'::jsonb,0,'Hazards can cause injury.','original'),
('127.618.d.2.B',4,'The agency whose rules a cosmetology student must follow in Texas is the:','["NFL", "TDLR", "NASA", "FIFA"]'::jsonb,1,'The Texas Department of Licensing and Regulation oversees the field.','original'),
