insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_80_v1'
from (values
('127.619.d.4.C',3,'Comparing product prices, delivery times and quality from different suppliers is:','["wasting time", "tipping", "locating and comparing vendors", "tardiness"]'::jsonb,2,'Choose vendors that offer the best value.','original'),
('127.619.d.4.C',4,'Why do salons compare vendors?','["to lose money", "to avoid orders", "to confuse clients", "to get the best value for the business and clients"]'::jsonb,3,'Value matters.','original'),
('127.619.d.4.D',3,'A haircut where all strands are combed straight out and cut to the same length at 90 degrees is a:','["ninety-degree cut", "forty-five degree cut", "no-angle cut", "zero-degree cut"]'::jsonb,0,'Elevation determines layers.','original'),
('127.619.d.4.D',4,'A zero-degree cut, in which hair falls straight down with no elevation, creates:','["heavy layers", "a solid, blunt shape", "wispy bangs only", "a curly shape"]'::jsonb,1,'No elevation builds weight.','original'),
('127.619.d.4.E',3,'Shaping and polishing fingernails and hands is a:','["facial", "shampoo", "manicure", "pedicure"]'::jsonb,2,'A manicure treats hands and nails.','original'),
('127.619.d.4.E',4,'A service that cleanses and treats the skin of the face is a:','["manicure", "blow dry", "haircut", "facial"]'::jsonb,3,'Facials care for facial skin.','original'),
('127.619.d.4.F',3,'Curling hair around a heated iron is a form of:','["thermal styling", "coloring", "relaxing", "bleaching"]'::jsonb,0,'Heat styling uses irons.','original'),
('127.619.d.4.F',4,'Drying and styling wet hair with a handheld dryer and brush is called:','["trimming", "blow drying", "perming", "shampooing only"]'::jsonb,1,'Blow drying shapes hair as it dries.','original'),
('127.620.d.1.A',3,'Wearing clean, neat, appropriate clothing to work in a salon shows:','["rebellion", "apathy", "professionalism", "carelessness"]'::jsonb,2,'Attire reflects professionalism.','original'),
('127.620.d.1.A',4,'Which outfit choice is most appropriate for a salon internship?','["torn clothes", "wet clothes", "pajamas", "clean, neat attire that meets the dress code"]'::jsonb,3,'Dress codes protect image and safety.','original'),
('127.620.d.1.B',3,'Speaking clearly and writing correct emails to clients are examples of effective:','["communication", "delay", "avoidance", "isolation"]'::jsonb,0,'Good communication builds trust.','original'),
('127.620.d.1.B',4,'A stylist adjusts how she speaks to a client who uses a different first language. She is communicating effectively with:','["only coworkers", "diverse individuals", "no one", "only family"]'::jsonb,1,'Communication adapts to the listener.','original'),
('127.620.d.1.C',3,'Taking responsibility for the quality of your own work is called personal:','["rivalry", "doubt", "ownership", "luck"]'::jsonb,2,'Ownership means accountability.','original'),
('127.620.d.1.C',4,'If a color result is off, a stylist who shows ownership will:','["blame the client", "hide the mistake", "ignore the complaint", "admit it and work to correct it"]'::jsonb,3,'Accountability builds trust.','original'),
('127.620.d.1.D',3,'Starting your own salon is an example of:','["entrepreneurship", "unemployment", "retirement", "volunteerism"]'::jsonb,0,'Entrepreneurs start businesses.','original'),
('127.620.d.1.D',4,'Which is an entrepreneurial path in cosmetology?','["retiring early", "owning a salon or renting a booth", "staying unlicensed", "avoiding clients"]'::jsonb,1,'Owners take on business risks and rewards.','original'),
('127.620.d.1.E',3,'A document that lists your education, skills and experience for employers is a:','["receipt", "invoice", "resume", "ticket"]'::jsonb,2,'A resume markets your qualifications.','original'),
('127.620.d.1.E',4,'Which should a resume for a cosmetology job include?','["favorite foods", "family arguments", "bank passwords", "contact information, skills and training"]'::jsonb,3,'Resumes list job-related facts.','original'),
('127.620.d.2.A',3,'In a work setting, health and safety policies exist to protect:','["clients and staff", "only inspectors", "only vendors", "only owners"]'::jsonb,0,'Safety applies to everyone.','original'),
('127.620.d.2.A',4,'A student at a salon placement sees a posted safety rule. The best response is to:','["ignore it", "follow it every time", "ask others to follow it", "follow it only when watched"]'::jsonb,1,'Rules must be followed consistently.','original'),
('127.620.d.2.B',3,'Wiping counters and implements with an approved product to kill germs is:','["skipping", "guessing", "disinfecting", "decorating"]'::jsonb,2,'Disinfecting limits infection.','original'),
('127.620.d.2.B',4,'Cleaning should be done _____ disinfecting a surface.','["never prior to", "after", "instead of ignoring", "before"]'::jsonb,3,'Dirt reduces disinfectant effectiveness.','original'),
('127.620.d.2.C',3,'Spotting a slippery floor and cleaning it up quickly is a technique to avoid:','["hazards", "orders", "profits", "breaks"]'::jsonb,0,'Prevention avoids accidents.','original'),
('127.620.d.2.C',4,'Which technique helps a stylist avoid a chemical hazard?','["skipping ventilation", "reading product labels and wearing gloves", "mixing unknown products", "touching eyes during service"]'::jsonb,1,'Labels and protective gear reduce exposure.','original'),
('127.620.d.2.D',3,'Dye, chemical waste and used blades must be thrown away following:','["random habit", "trial and error", "industry best practices", "personal taste"]'::jsonb,2,'Proper disposal protects people and environment.','original'),
('127.620.d.2.D',4,'Used razor blades should go into a:','["open drawer", "paper bag", "regular trash can", "puncture-resistant container"]'::jsonb,3,'Sharps need special containers.','original'),
('127.620.d.3.A',3,'Showing you can handle scissors, clippers and flat irons correctly demonstrates:','["safe and effective tool use", "careless work", "random choices", "slow service"]'::jsonb,0,'Competence includes safety.','original'),
('127.620.d.3.A',4,'A stylist notices a clipper blade is dull and chipped. The best action is to:','["lend it to a coworker", "replace or sharpen it before use", "use it anyway", "hide the damage"]'::jsonb,1,'Damaged tools can cause injury.','original'),
('127.620.d.3.B',3,'Using a stool and mat that reduce strain helps promote professional:','["clutter", "fatigue", "efficiency", "delay"]'::jsonb,2,'Ergonomics improves work.','original'),
('127.620.d.3.B',4,'Working with raised arms for long periods without breaks can lead to:','["faster growth", "better balance", "longer hair", "shoulder strain"]'::jsonb,3,'Poor posture causes injury.','original'),
('127.620.d.3.C',3,'Comparing two scheduling apps and choosing the one that best fits the salon is:','["critiquing and selecting technology", "wasting time", "delaying work", "ignoring needs"]'::jsonb,0,'Choose tools based on need.','original'),
('127.620.d.3.C',4,'When choosing a salon technology resource, the most useful question is:','["Is it the oldest?", "Does it meet our needs and budget?", "Is it the largest?", "Is it the loudest?"]'::jsonb,1,'Fit and cost matter.','original'),
('127.620.d.4.A',3,'A stylist asks a new client questions about hair history and goals. This is:','["cleaning", "payroll", "client consultation", "small talk only"]'::jsonb,2,'Consultation guides services.','original'),
('127.620.d.4.A',4,'A client wants a color that does not suit her skin tone. A good consultation skill is to:','["do it silently", "refuse to speak", "make fun of the choice", "explain options respectfully and agree on a plan"]'::jsonb,3,'Guide the client to a good result.','original'),
('127.620.d.4.B',3,'Software that stores client contact details, appointments and service history is a:','["client management system", "hair dryer", "camera", "calculator"]'::jsonb,0,'It keeps records in one place.','original'),
('127.620.d.4.B',4,'When selecting a client management system, a salon should consider:','["only the price of coffee", "ease of use and features needed", "only the color of the logo", "only the owner''s pet"]'::jsonb,1,'Choose what fits operations.','original'),
('127.620.d.4.C',3,'Recording formulas used and how the client felt about the result creates:','["delays", "rumors", "documentation", "errors"]'::jsonb,2,'Records help repeat or adjust services.','original'),
('127.620.d.4.C',4,'Why document client satisfaction after each service?','["to fill time", "to gossip", "to avoid payment", "to improve future visits"]'::jsonb,3,'Feedback guides future consultation.','original'),
('127.620.d.5.A',3,'A stylist demonstrates a forty-five degree haircut. This is an example of a:','["basic haircut technique", "color formula", "manicure", "chemical service"]'::jsonb,0,'Haircuts use set angles.','original'),
('127.620.d.5.A',4,'The angle at which hair is lifted from the head before cutting is the:','["shade", "elevation", "porosity", "texture"]'::jsonb,1,'Elevation affects shape and layering.','original'),
('127.620.d.5.B',3,'Filing, shaping and polishing the nails is part of a:','["relaxer", "pedicure only", "manicure", "shampoo"]'::jsonb,2,'A manicure treats hands and nails.','original'),
('127.620.d.5.B',4,'Before applying polish in a manicure, the nails should be:','["oiled heavily", "left dirty", "soaked in dye", "cleaned and shaped"]'::jsonb,3,'Preparation ensures good polish application.','original'),
('127.620.d.5.C',3,'Cleansing, steaming and applying a mask to the face is part of a basic:','["facial service", "blow dry", "haircut", "manicure"]'::jsonb,0,'Facials care for the skin.','original'),
('127.620.d.5.C',4,'In a facial, cleansing the skin before treatment removes:','["natural oils entirely", "dirt and makeup", "all moisture", "skin cells permanently"]'::jsonb,1,'A clean base is needed.','original'),
('127.620.d.5.D',3,'Applying relaxer, hair color or lightener are examples of:','["haircut angles", "manicure steps", "chemical services", "blow-dry tools"]'::jsonb,2,'Chemicals change hair structure or color.','original'),
('127.620.d.5.D',4,'Before most chemical services, a stylist should perform a:','["manicure", "blow dry only", "haircut only", "strand test or patch test"]'::jsonb,3,'Tests check for allergic reactions or damage.','original'),
('127.620.d.5.E',3,'Wetting, lathering and rinsing a client''s hair is a basic:','["shampooing technique", "permanent wave", "thermal style", "facial step"]'::jsonb,0,'Shampooing cleans hair and scalp.','original'),
('127.620.d.5.E',4,'While shampooing, the stylist uses the pads of the fingers rather than the nails to protect the:','["floor", "scalp", "towel", "sink"]'::jsonb,1,'Nails can scratch the scalp.','original'),
('127.620.d.5.F',3,'Wrapping hair around rods and applying a solution to create lasting curls is a:','["shampoo", "blow dry", "permanent wave", "manicure"]'::jsonb,2,'Permanent waves change hair shape.','original'),
('127.620.d.5.F',4,'The step in a permanent wave that rebuilds the hair''s bonds in its new shape is the:','["conditioner only", "toner", "clarifier", "neutralizer"]'::jsonb,3,'Neutralizer sets the curl.','original'),
('127.620.d.5.G',3,'Forming temporary curls with a curling iron is a basic:','["curling technique", "shampoo step", "perming step", "manicure step"]'::jsonb,0,'Heat curls last until washed.','original'),
('127.620.d.5.G',4,'To avoid burning the client, a stylist should check the iron''s:','["color", "temperature", "brand", "price"]'::jsonb,1,'Heat settings affect safety.','original'),
('127.620.d.5.H',3,'Using a dryer, a brush and a nozzle to shape hair is basic:','["relaxing", "perming", "blow drying", "dyeing"]'::jsonb,2,'Blow drying shapes hair.','original'),
('127.620.d.5.H',4,'Pointing the dryer nozzle down the hair shaft helps close the cuticle and add:','["frizz", "dryness", "damage", "smoothness and shine"]'::jsonb,3,'Direction of airflow matters.','original'),
('127.620.d.5.I',3,'Flat irons and curling irons use heat to style hair. This category is:','["thermal styling", "manual styling only", "chemical styling", "wet styling only"]'::jsonb,0,'Thermal means heat.','original')
