('127.622.d.2.B',3,'Cleaning combs, brushes and stations with an approved product is part of:','["decorating", "advertising", "disinfecting the work area", "hiring"]'::jsonb,2,'Disinfection stops germs.','original'),
('127.622.d.2.B',4,'Which should happen between clients?','["stations are left dirty", "tools are shared as is", "towels are reused unwashed", "tools and surfaces are cleaned and disinfected"]'::jsonb,3,'Prevents cross-contamination.','original'),
